-- Run via SQL against the intended Neon branch as an authorized database owner.
-- IMPORTANT: create limited roles through SQL, NOT Neon Console/API/CLI. Those
-- interfaces grant neon_superuser membership and are not suitable for app runtime.
-- Replace the placeholder with a unique secret generated by a password manager.
-- Do not commit the real password or store it in source control.
-- Run only once per branch; if the role already exists, inspect it instead of rerunning.

CREATE ROLE ingenieroai_runtime
  WITH LOGIN
  PASSWORD 'REPLACE_WITH_A_UNIQUE_RANDOM_SECRET'
  NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;

